foreach ($rel in $map.Keys) {
    $folderPath = if ($rel -eq "") { $targetRoot } else { Join-Path $targetRoot $rel }
    if (Test-Path $folderPath) {
        try {
            $acl = Get-Acl -LiteralPath $folderPath
            $acl.SetSecurityDescriptorSddlForm($map[$rel], [System.Security.AccessControl.AccessControlSections]::Access)
            Set-Acl -LiteralPath $folderPath -AclObject $acl
            Write-Host "Set-Acl OK for: '$rel'"
        } catch {
            Write-Host "ERROR on '$rel': $_"
        }
    }
}
